import {openSQLiteStore} from '../../src/services/storage/sqlite.js';import {createSQLiteBotDatabase} from '../../src/services/storage/sqliteBotDatabase.js';import {db} from '../../src/utils/database/wrapper.js';import {getTicketData,saveTicketData} from '../../src/utils/database/tickets.js';
const [file,guild,channel,operation]=process.argv.slice(2),sqlite=await openSQLiteStore({path:file,busyTimeout:5000});db.db=createSQLiteBotDatabase(sqlite);db.initialized=true;db.useFallback=false;const ticket=await getTicketData(guild,channel);process.send('ready');process.on('message',async message=>{if(message!=='go')return;try{if(operation==='close')ticket.status='closed';else ticket.claimedBy='456789012345678901';await saveTicketData(guild,channel,ticket);process.send('saved')}catch(error){process.send(error.code||'error')}finally{sqlite.close();process.disconnect()}});
